_DownloaderFormSheet:
class _DownloaderFormSheet extends StatefulWidget {
  final Downloader? downloader;
  const _DownloaderFormSheet({this.downloader});
  @override
  State<_DownloaderFormSheet> createState() => _DownloaderFormSheetState();
}

class _DownloaderFormSheetState extends State<_DownloaderFormSheet> {
  final _api = DownloaderApi();
  late final TextEditingController _name, _url, _username, _password;
  String _type = 'qb';
  bool _isDefault = false;
  bool _saving = false;

  bool get _isEdit => widget.downloader != null;

  @override
  void initState() {
    super.initState();
    final d = widget.downloader;
    _name = TextEditingController(text: d?.name ?? '');
    _url = TextEditingController(text: d?.url ?? '');
    _username = TextEditingController(text: d?.username ?? '');
    _password = TextEditingController(); // 编辑态留空=不修改
    _type = d?.type ?? 'qb';
    _isDefault = d?.isDefault ?? false;
  }

  @override
  void dispose() {
    _name.dispose();
    _url.dispose();
    _username.dispose();
    _password.dispose();
    super.dispose();
  }

  void _toast(String m) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(m)));
  }

  Future<void> _submit() async {
    final name = _name.text.trim();
    final url = _url.text.trim();
    if (name.isEmpty || url.isEmpty) {
      _toast('名称与地址必填');
      return;
    }
    if (!RegExp(r'^https?://.+').hasMatch(url)) {
      _toast('地址需以 http:// 或 https:// 开头');
      return;
    }
    setState(() => _saving = true);
    try {
      if (_isEdit) {
        await _api.update(
          widget.downloader!.id,
          name: name,
          type: _type,
          url: url,
          username: _username.text.trim(),
          password: _password.text,
          isDefault: _isDefault,
        );
        _toast('已更新');
      } else {
        await _api.add(
          name: name,
          type: _type,
          url: url,
          username: _username.text.trim(),
          password: _password.text,
        );
        _toast('已添加');
      }
      if (mounted) Navigator.pop(context, true);
    } catch (e) {
      _toast(e.toString().replaceFirst('Exception: ', ''));
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    // 标题与键盘避让由 showAdaptiveSheet 浮层容器统一处理（宽屏对话框 / 窄屏底栏）。
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        TextField(
          controller: _name,
          decoration: const InputDecoration(labelText: '名称'),
        ),
        const SizedBox(height: 12),
        DropdownButtonFormField<String>(
          initialValue: _type,
          decoration: const InputDecoration(labelText: '类型'),
          items: [
            DropdownMenuItem(value: 'qb', child: _dlOption(_dlMeta('qb'))),
            DropdownMenuItem(value: 'tr', child: _dlOption(_dlMeta('tr'))),
            DropdownMenuItem(value: 'ut', child: _dlOption(_dlMeta('ut'))),
            DropdownMenuItem(value: 'dl', child: _dlOption(_dlMeta('dl'))),
            DropdownMenuItem(value: 'ar', child: _dlOption(_dlMeta('ar'))),
            DropdownMenuItem(value: 'rt', child: _dlOption(_dlMeta('rt'))),
            DropdownMenuItem(value: 'fl', child: _dlOption(_dlMeta('fl'))),
          ],
          onChanged: (v) => setState(() => _type = v ?? 'qb'),
        ),
        const SizedBox(height: 12),
        TextField(
          controller: _url,
          decoration: const InputDecoration(
            labelText: '地址',
            hintText: 'http://127.0.0.1:8080',
          ),
          keyboardType: TextInputType.url,
        ),
        const SizedBox(height: 12),
        TextField(
          controller: _username,
          decoration: const InputDecoration(labelText: '用户名'),
        ),
        const SizedBox(height: 12),
        TextField(
          controller: _password,
          obscureText: true,
          decoration: InputDecoration(
            labelText: '密码',
            hintText: _isEdit ? '留空不修改' : null,
          ),
        ),
        if (_isEdit)
          SwitchListTile(
            value: _isDefault,
            onChanged: (v) => setState(() => _isDefault = v),
            title: const Text('设为默认下载器'),
            contentPadding: EdgeInsets.zero,
            dense: true,
          ),
        const SizedBox(height: 20),
        Row(
          mainAxisAlignment: MainAxisAlignment.end,
          children: [
            TextButton(
              onPressed: _saving ? null : () => Navigator.pop(context, false),
              child: const Text('取消'),
            ),
            const SizedBox(width: 8),
            FilledButton(
              onPressed: _saving ? null : _submit,
              child: Text(_isEdit ? '保存' : '添加'),
            ),
          ],
        ),
      ],
    );
  }
}

_TorrentSheet:
class _TorrentSheet extends StatefulWidget {
  final Downloader downloader;
  const _TorrentSheet({required this.downloader});
  @override
  State<_TorrentSheet> createState() => _TorrentSheetState();
}

class _TorrentSheetState extends State<_TorrentSheet> {
  final _ws = WsClient();
  final _api = DownloaderApi();
  List<Torrent> _torrents = [];
  int? _dlRate;
  int? _upRate;
  String _error = '';
  bool _connecting = true;
  StreamSubscription? _sub;

  int get _id => widget.downloader.id;
  String get _type => widget.downloader.type;

  @override
  void initState() {
    super.initState();
    _ws.connect();
    _sub = _ws.snapshots.listen((list) {
      final match = list.where((s) => s.downloaderId == _id).toList();
      if (match.isEmpty) return; // 本次广播不含此下载器，保留上次显示
      final s = match.first;
      if (!mounted) return;
      setState(() {
        _torrents = s.torrents;
        _dlRate = s.dlRate;
        _upRate = s.upRate;
        _error = s.error;
        _connecting = false;
      });
    });
  }

  @override
  void dispose() {
    _sub?.cancel(); // 仅取消本页订阅，不断开共享的 WsClient
    super.dispose();
  }

  void _toast(String m) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(m)));
  }

  String _cleanErr(Object e) => e.toString().replaceFirst('Exception: ', '');

  Future<void> _act(Future<void> Function() fn, String ok) async {
    try {
      await fn();
      _toast(ok);
    } catch (e) {
      _toast(_cleanErr(e));
    }
  }

  int get _active =>
      _torrents.where((t) => t.state.contains('download')).length;
  int get _seeding => _torrents
      .where((t) => t.state.contains('upload') || t.state.contains('seed'))
      .length;
  int get _paused => _torrents
      .where((t) => t.state.contains('pause') || t.state.contains('stop'))
      .length;

  Future<bool?> _confirmDelete(String name) async {
    bool delFiles = false;
    return showDialog<bool>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setS) => AlertDialog(
          title: const Text('删除任务'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text('确认删除「$name」？'),
              CheckboxListTile(
                value: delFiles,
                onChanged: (v) => setS(() => delFiles = v ?? false),
                title: const Text('同时删除文件'),
                controlAffinity: ListTileControlAffinity.leading,
                dense: true,
                contentPadding: EdgeInsets.zero,
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx, null),
              child: const Text('取消'),
            ),
            TextButton(
              onPressed: () => Navigator.pop(ctx, delFiles),
              child: const Text('删除'),
            ),
          ],
        ),
      ),
    );
  }

  Future<String?> _input(
    String title,
    String hint, {
    String initial = '',
  }) async {
    final ctrl = TextEditingController(text: initial);
    return showDialog<String>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(title),
        content: TextField(
          controller: ctrl,
          decoration: InputDecoration(hintText: hint),
          autofocus: true,
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx),
            child: const Text('取消'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, ctrl.text.trim()),
            child: const Text('确定'),
          ),
        ],
      ),
    );
  }

  void _onMenu(String val, Torrent t) async {
    switch (val) {
      case 'detail':
        _showDetail(t);
      case 'pause':
        _act(() => _api.pause(_id, [t.hash]), '已暂停');
      case 'resume':
        _act(() => _api.resume(_id, [t.hash]), '已恢复');
      case 'recheck':
        _act(() => _api.recheck(_id, [t.hash]), '已发起校验');
      case 'reannounce':
        _act(() => _api.reannounce(_id, [t.hash]), '已重新汇报');
      case 'forceStart':
        _act(() => _api.setForceStart(_id, [t.hash], !t.forceStart), '已切换强制开始');
      case 'top':
        _act(() => _api.setQueuePriority(_id, [t.hash], 'top'), '已置顶');
      case 'up':
        _act(() => _api.setQueuePriority(_id, [t.hash], 'up'), '已上移');
      case 'down':
        _act(() => _api.setQueuePriority(_id, [t.hash], 'down'), '已下移');
      case 'bottom':
        _act(() => _api.setQueuePriority(_id, [t.hash], 'bottom'), '已置底');
      case 'seq':
        _act(() => _api.toggleSequential(_id, [t.hash]), '已切换顺序下载');
      case 'firstlast':
        _act(() => _api.toggleFirstLast(_id, [t.hash]), '已切换首尾优先');
      case 'copyMagnet':
        _copy(t.magnet, '磁力链');
      case 'copyHash':
        _copy(t.infoHash.isNotEmpty ? t.infoHash : t.hash, '哈希');
      case 'remove':
        final df = await _confirmDelete(t.name);
        if (df != null) {
          _act(
            () => _api.removeTorrents(_id, [t.hash], deleteFiles: df),
            '已删除',
          );
        }
      case 'category':
        await _editCategory(t);
      case 'tags':
        await _editTags(t);
      case 'limits':
        await _editLimits(t);
      case 'shareLimits':
        await _editShareLimits(t);
      case 'files':
        _showFiles(t);
      case 'trackers':
        _showTrackers(t);
      case 'peers':
        _showPeers(t);
      case 'manageCats':
        _showCategoryManager();
    }
  }

  Future<void> _copy(String text, String label) async {
    await Clipboard.setData(ClipboardData(text: text));
    _toast('$label已复制');
  }

  Future<void> _editShareLimits(Torrent t) async {
    String ratioMode = 'global';
    String seedMode = 'global';
    String ratioInput = '';
    String seedInput = '';
    final ok = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      showDragHandle: true,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setS) => Padding(
          // 键盘避让：sheet 底部按视图插入区抬高，输入框不被遮挡。
          padding: EdgeInsets.only(
            bottom: MediaQuery.of(ctx).viewInsets.bottom,
          ),
          child: SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  '做种限制',
                  style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700),
                ),
                const SizedBox(height: 16),
                const Text('分享比率', style: TextStyle(fontSize: 13)),
                DropdownButton<String>(
                  isExpanded: true,
                  value: ratioMode,
                  items: const [
                    DropdownMenuItem(value: 'global', child: Text('全局默认')),
                    DropdownMenuItem(value: 'unlimited', child: Text('无限')),
                    DropdownMenuItem(value: 'custom', child: Text('自定义')),
                  ],
                  onChanged: (v) => setS(() => ratioMode = v!),
                ),
                if (ratioMode == 'custom')
                  TextField(
                    keyboardType: const TextInputType.numberWithOptions(
                      decimal: true,
                    ),
                    decoration: const InputDecoration(hintText: '如 2.0'),
                    onChanged: (v) => ratioInput = v,
                  ),
                const SizedBox(height: 12),
                Text(
                  '做种时长${_type == 'tr' ? '（空闲）' : ''}',
                  style: const TextStyle(fontSize: 13),
                ),
                DropdownButton<String>(
                  isExpanded: true,
                  value: seedMode,
                  items: const [
                    DropdownMenuItem(value: 'global', child: Text('全局默认')),
                    DropdownMenuItem(value: 'unlimited', child: Text('无限')),
                    DropdownMenuItem(value: 'custom', child: Text('自定义')),
                  ],
                  onChanged: (v) => setS(() => seedMode = v!),
                ),
                if (seedMode == 'custom')
                  TextField(
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(hintText: '分钟'),
                    onChanged: (v) => seedInput = v,
                  ),
                if (_type == 'tr')
                  Padding(
                    padding: EdgeInsets.only(top: 8),
                    child: Text(
                      'TR 做种时长为「空闲时长」语义',
                      style: TextStyle(fontSize: 11, color: context.dimText),
                    ),
                  ),
                const SizedBox(height: 20),
                Row(
                  mainAxisAlignment: MainAxisAlignment.end,
                  children: [
                    TextButton(
                      onPressed: () => Navigator.pop(ctx, false),
                      child: const Text('取消'),
                    ),
                    const SizedBox(width: 8),
                    FilledButton(
                      onPressed: () => Navigator.pop(ctx, true),
                      child: const Text('确定'),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      ),
    );
    if (ok != true) return;
    final ratio = ratioMode == 'global'
        ? -1.0
        : ratioMode == 'unlimited'
        ? -2.0
        : (double.tryParse(ratioInput) ?? 0);
    final seed = seedMode == 'global'
        ? -1
        : seedMode == 'unlimited'
        ? -2
        : (int.tryParse(seedInput) ?? 0);
    _act(
      () => _api.setShareLimits(_id, [
        t.hash,
      ], ShareLimits(ratioLimit: ratio, seedingTimeLimit: seed)),
      '已设置',
    );
  }

  void _showPeers(Torrent t) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      builder: (_) => FractionallySizedBox(
        heightFactor: 0.82,
        child: _PeersSheet(id: _id, hash: t.hash),
      ),
    );
  }

  void _showDetail(Torrent t) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      showDragHandle: true,
      useSafeArea: true,
      builder: (_) => DraggableScrollableSheet(
        expand: false,
        initialChildSize: 0.55,
        minChildSize: 0.35,
        maxChildSize: 0.92,
        builder: (ctx, scrollCtrl) => _DetailSheet(
          id: _id,
          type: _type,
          torrent: t,
          scrollController: scrollCtrl,
        ),
      ),
    );
  }


  void _showCategoryManager() {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      builder: (_) => FractionallySizedBox(
        heightFactor: 0.82,
        child: _CategorySheet(id: _id),
      ),
    );
  }

  Future<void> _editCategory(Torrent t) async {
    try {
      final cats = await _api.categories(_id);
      if (!mounted) return;
      final sel = await showDialog<String>(
        context: context,
        builder: (ctx) => SimpleDialog(
          title: const Text('设置分类'),
          children: [
            ...cats.map(
              (c) => SimpleDialogOption(
                onPressed: () => Navigator.pop(ctx, c),
                child: Text(c),
              ),
            ),
            SimpleDialogOption(
              onPressed: () => Navigator.pop(ctx, ''),
              child: Text('（清除）', style: TextStyle(color: context.dimText)),
            ),
          ],
        ),
      );
      if (sel != null) _act(() => _api.setCategory(_id, [t.hash], sel), '已设置');
    } catch (_) {
      _toast('加载分类失败');
    }
  }

  Future<void> _editTags(Torrent t) async {
    final s = await _input('设置标签', '逗号分隔，覆盖现有', initial: t.tags.join(','));
    if (s == null) return;
    final tags = s
        .split(',')
        .map((e) => e.trim())
        .where((e) => e.isNotEmpty)
        .toList();
    _act(() => _api.editTags(_id, [t.hash], tags, 'set'), '已设置');
  }

  Future<void> _editLimits(Torrent t) async {
    final up = await _input('上传限速', 'KB/s，0=不限');
    if (up == null) return;
    final dl = await _input('下载限速', 'KB/s，0=不限');
    if (dl == null) return;
    final upB = (int.tryParse(up) ?? 0) * 1024;
    final dlB = (int.tryParse(dl) ?? 0) * 1024;
    _act(
      () => _api.setLimits(_id, [
        t.hash,
      ], Limits(uploadLimit: upB, downloadLimit: dlB)),
      '已设置',
    );
  }

  void _showFiles(Torrent t) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      builder: (_) => FractionallySizedBox(
        heightFactor: 0.7,
        child: _FilesSheet(id: _id, hash: t.hash, type: _type),
      ),
    );
  }

  void _showTrackers(Torrent t) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      builder: (_) => FractionallySizedBox(
        heightFactor: 0.7,
        child: _TrackersSheet(id: _id, hash: t.hash),
      ),
    );
  }

  void _add() {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      builder: (_) => Padding(
        padding: EdgeInsets.only(
          bottom: MediaQuery.of(context).viewInsets.bottom,
        ),
        child: _AddTorrentSheet(downloader: widget.downloader),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final d = widget.downloader;
    Widget body;
    if (_connecting) {
      body = Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            CircularProgressIndicator(),
            const SizedBox(height: 12),
            Text('连接实时推送…', style: TextStyle(color: context.dimText)),
          ],
        ),
      );
    } else if (_error.isNotEmpty) {
      body = Center(
        child: Text(
          '拉取失败：$_error',
          style: TextStyle(color: Colors.redAccent),
        ),
      );
    } else if (_torrents.isEmpty) {
      body = Center(
        child: Text('无任务', style: TextStyle(color: context.dimText)),
      );
    } else {
      body = ListView.separated(
        itemCount: _torrents.length,
        separatorBuilder: (_, _) =>
            const Divider(height: 1, indent: 12, endIndent: 12),
        itemBuilder: (_, i) => _row(_torrents[i]),
      );
    }
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.all(14),
          child: Row(
            children: [
              Text(
                '${d.name} · 任务',
                style: const TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w600,
                ),
              ),
              const Spacer(),
              if (_dlCaps(_type).categoryCRUD)
                IconButton(
                  icon: const Icon(Icons.category_outlined),
                  onPressed: _showCategoryManager,
                  tooltip: '分类管理',
                ),
              IconButton(
                icon: const Icon(Icons.add_circle_outline),
                onPressed: _add,
                tooltip: '添加种子',
              ),
              const SizedBox(width: 4),
              Container(
                width: 8,
                height: 8,
                decoration: BoxDecoration(
                  color: _ws.isConnected ? PTColors.success : context.dimText,
                  shape: BoxShape.circle,
                ),
              ),
            ],
          ),
        ),
        _statsRow(),
        const Divider(height: 1),
        Expanded(child: body),
      ],
    );
  }

  Widget _statsRow() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 4, 14, 10),
      child: Row(
        children: [
          _stat('↓', _fmtSpeed(_dlRate), PTColors.primary2),
          const SizedBox(width: 16),
          _stat('↑', _fmtSpeed(_upRate), PTColors.success),
          const Spacer(),
          _count('下载', _active),
          const SizedBox(width: 12),
          _count('做种', _seeding),
          const SizedBox(width: 12),
          _count('暂停', _paused),
        ],
      ),
    );
  }

  Widget _stat(String arrow, String speed, Color color) {
    return Row(
      children: [
        Text(arrow, style: TextStyle(color: color, fontSize: 14)),
        const SizedBox(width: 4),
        Text(
          speed,
          style: TextStyle(
            color: color,
            fontWeight: FontWeight.w600,
            fontSize: 13,
          ),
        ),
      ],
    );
  }

  Widget _count(String label, int n) {
    return Text(
      '$label $n',
      style: TextStyle(color: context.dimText, fontSize: 12),
    );
  }

  bool _isPaused(Torrent t) =>
      t.state.contains('pause') || t.state.contains('stop');

  /// 左滑删除（可 SnackBar 撤销 4s）；右滑暂停/恢复（不移除行）。
  Widget _row(Torrent t) {
    final paused = _isPaused(t);
    return Dismissible(
      key: ValueKey('torrent-${t.hash}'),
      direction: DismissDirection.horizontal,
      confirmDismiss: (dir) async {
        if (dir == DismissDirection.startToEnd) {
          // 右滑：暂停 / 恢复，不移除列表项
          if (paused) {
            await _act(() => _api.resume(_id, [t.hash]), '已恢复');
          } else {
            await _act(() => _api.pause(_id, [t.hash]), '已暂停');
          }
          return false;
        }
        // 左滑：删除（确认是否删文件后，乐观移除 + 撤销）
        return _swipeDelete(t);
      },
      background: Container(
        color: (paused ? Colors.green : Colors.orange).withValues(alpha: 0.88),
        alignment: Alignment.centerLeft,
        padding: const EdgeInsets.only(left: 20),
        child: Row(
          children: [
            Icon(paused ? Icons.play_arrow : Icons.pause, color: Colors.white),
            const SizedBox(width: 8),
            Text(
              paused ? '恢复' : '暂停',
              style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w600),
            ),
          ],
        ),
      ),
      secondaryBackground: Container(
        color: Colors.red.withValues(alpha: 0.88),
        alignment: Alignment.centerRight,
        padding: const EdgeInsets.only(right: 20),
        child: const Row(
          mainAxisAlignment: MainAxisAlignment.end,
          children: [
            Text('删除', style: TextStyle(color: Colors.white, fontWeight: FontWeight.w600)),
            SizedBox(width: 8),
            Icon(Icons.delete_outline, color: Colors.white),
          ],
        ),
      ),
      child: ListTile(
        onTap: () => _showDetail(t),
